import { useBreakpointStore } from '../state/breakpointStore'
import type { Breakpoint, BreakpointKind, ScormApiMethod } from '@/shared/types'

/** Serializable, user-facing definition of a breakpoint (id/state generated by the store). */
export interface BreakpointDraft {
  kind: BreakpointKind
  method?: ScormApiMethod
  element?: string
  value?: string
  threshold?: number
}

/** Validation error message, or null when the draft is usable. */
export function validateBreakpointDraft(draft: BreakpointDraft): string | null {
  switch (draft.kind) {
    case 'api-call':
      return draft.method === undefined ? 'Choose a method to match.' : null
    case 'cmi-set':
      return draft.element === undefined || draft.element.trim() === ''
        ? 'An element path is required (e.g. cmi.core.score.raw).'
        : null
    case 'score-threshold':
      return draft.threshold === undefined || Number.isNaN(draft.threshold)
        ? 'A numeric threshold is required.'
        : null
    case 'objective-update':
      return null
  }
}

/** Short human-readable description of what a breakpoint matches. */
export function describeBreakpoint(breakpoint: Breakpoint): string {
  switch (breakpoint.kind) {
    case 'api-call':
      return [breakpoint.method, breakpoint.element].filter(Boolean).join(' ')
    case 'cmi-set':
      return [breakpoint.element, breakpoint.value !== undefined ? `= ${breakpoint.value}` : undefined]
        .filter(Boolean)
        .join(' ')
    case 'score-threshold':
      return `score.raw ≥ ${breakpoint.threshold ?? 0}`
    case 'objective-update':
      return breakpoint.element ?? 'any objective'
  }
}

/**
 * CRUD facade over the breakpoint store — the panel and future callers talk
 * to this, not the store directly. Pure helpers (validate/describe) live here
 * too so the UI stays free of matching logic.
 */
export const BreakpointService = {
  add(draft: BreakpointDraft): Breakpoint {
    const normalized: Omit<Breakpoint, 'id' | 'enabled' | 'hitCount'> = {
      kind: draft.kind,
      ...(draft.method !== undefined ? { method: draft.method } : {}),
      ...(draft.element !== undefined && draft.element.trim() !== ''
        ? { element: draft.element.trim() }
        : {}),
      ...(draft.value !== undefined && draft.value.trim() !== '' ? { value: draft.value } : {}),
      ...(draft.threshold !== undefined ? { threshold: draft.threshold } : {}),
    }
    return useBreakpointStore.getState().addBreakpoint(normalized)
  },

  remove: (id: string): void => useBreakpointStore.getState().removeBreakpoint(id),

  toggle: (id: string): void => useBreakpointStore.getState().toggleBreakpoint(id),

  clear: (): void => useBreakpointStore.getState().clearBreakpoints(),

  resume: (): void => useBreakpointStore.getState().resume(),
}
